var lab: Node = get_tree().current_scene
var regions: Array = []
for id: StringName in lab.manager.object_ids():
	var body: Node = lab.manager.get_body(id)
	regions.append({"id":id,"owner":body.structure_id,"material":body.material_kind,"forms":body.colliders.size(),"builds":body.shape_builds})
return {"scene":lab.scene_file_path,"replay":lab.get_node("Replay").get_status(),"regions":regions,"logical_structures":lab.adapter.logical_active.keys(),"physics_ticks_per_second":Engine.physics_ticks_per_second,"network_receiver_nodes_absent":lab.get_node_or_null("StructureUdpReceiver")==null and lab.get_node_or_null("ExternalPlatformReceiver")==null}
